use std::collections::{HashMap, HashSet};
use std::hash::Hash;

// ══════════════════════════════════════════════════════════════
// 类型别名 — 对齐 Python 命名
// ══════════════════════════════════════════════════════════════

pub type List<T> = Vec<T>;
pub type Dict<K, V> = HashMap<K, V>;
pub type Set<T> = HashSet<T>;

// ══════════════════════════════════════════════════════════════
// Vec / List 扩展方法
// ══════════════════════════════════════════════════════════════

pub trait ListExt<T> {
    fn lz_push(&mut self, item: T);
    fn lz_pop(&mut self) -> Option<T>;
    fn lz_len(&self) -> i64;
    fn lz_get(&self, index: i64) -> Option<&T>;
    fn lz_set(&mut self, index: i64, value: T);
    fn lz_contains(&self, item: &T) -> bool
    where
        T: PartialEq;
    fn lz_index(&self, item: &T) -> Option<i64>
    where
        T: PartialEq;
    fn lz_remove(&mut self, index: i64) -> T;
    fn lz_insert(&mut self, index: i64, item: T);
    fn lz_sort(&mut self)
    where
        T: Ord;
    fn lz_reverse(&mut self);
    fn lz_extend(&mut self, other: Vec<T>);
    fn lz_clear(&mut self);
    fn lz_is_empty(&self) -> bool;
    fn lz_first(&self) -> Option<&T>;
    fn lz_last(&self) -> Option<&T>;
    fn lz_slice(&self, start: i64, end: i64) -> Vec<T>
    where
        T: Clone;
}

impl<T> ListExt<T> for Vec<T> {
    fn lz_push(&mut self, item: T) {
        self.push(item);
    }
    fn lz_pop(&mut self) -> Option<T> {
        self.pop()
    }
    fn lz_len(&self) -> i64 {
        self.len() as i64
    }
    fn lz_get(&self, index: i64) -> Option<&T> {
        if index >= 0 {
            self.get(index as usize)
        } else {
            None
        }
    }
    fn lz_set(&mut self, index: i64, value: T) {
        if index >= 0 && (index as usize) < self.len() {
            self[index as usize] = value;
        }
    }
    fn lz_contains(&self, item: &T) -> bool
    where
        T: PartialEq,
    {
        self.contains(item)
    }
    fn lz_index(&self, item: &T) -> Option<i64>
    where
        T: PartialEq,
    {
        self.iter().position(|x| x == item).map(|i| i as i64)
    }
    fn lz_remove(&mut self, index: i64) -> T {
        self.remove(index as usize)
    }
    fn lz_insert(&mut self, index: i64, item: T) {
        self.insert(index as usize, item);
    }
    fn lz_sort(&mut self)
    where
        T: Ord,
    {
        self.sort();
    }
    fn lz_reverse(&mut self) {
        self.reverse();
    }
    fn lz_extend(&mut self, other: Vec<T>) {
        self.extend(other);
    }
    fn lz_clear(&mut self) {
        self.clear();
    }
    fn lz_is_empty(&self) -> bool {
        self.is_empty()
    }
    fn lz_first(&self) -> Option<&T> {
        self.first()
    }
    fn lz_last(&self) -> Option<&T> {
        self.last()
    }
    fn lz_slice(&self, start: i64, end: i64) -> Vec<T>
    where
        T: Clone,
    {
        if start < 0 || end < 0 {
            return vec![];
        }
        let s = start as usize;
        let e = (end as usize).min(self.len());
        if s >= e {
            return vec![];
        }
        self[s..e].to_vec()
    }
}

// ══════════════════════════════════════════════════════════════
// HashMap / Dict 扩展方法
// ══════════════════════════════════════════════════════════════

pub trait DictExt<K, V> {
    fn lz_get(&self, key: &K) -> Option<&V>
    where
        K: Eq + Hash;
    fn lz_set(&mut self, key: K, value: V)
    where
        K: Eq + Hash;
    fn lz_contains(&self, key: &K) -> bool
    where
        K: Eq + Hash;
    fn lz_remove(&mut self, key: &K) -> Option<V>
    where
        K: Eq + Hash;
    fn lz_keys(&self) -> Vec<&K>;
    fn lz_values(&self) -> Vec<&V>;
    fn lz_items(&self) -> Vec<(&K, &V)>;
    fn lz_len(&self) -> i64;
    fn lz_is_empty(&self) -> bool;
    fn lz_clear(&mut self);
    fn lz_update(&mut self, other: HashMap<K, V>)
    where
        K: Eq + Hash;
    fn lz_set_default(&mut self, key: K, default: V) -> &V
    where
        K: Clone + Eq + Hash,
        V: Clone;
}

impl<K: Eq + Hash, V> DictExt<K, V> for HashMap<K, V> {
    fn lz_get(&self, key: &K) -> Option<&V> {
        self.get(key)
    }
    fn lz_set(&mut self, key: K, value: V) {
        self.insert(key, value);
    }
    fn lz_contains(&self, key: &K) -> bool {
        self.contains_key(key)
    }
    fn lz_remove(&mut self, key: &K) -> Option<V> {
        self.remove(key)
    }
    fn lz_keys(&self) -> Vec<&K> {
        self.keys().collect()
    }
    fn lz_values(&self) -> Vec<&V> {
        self.values().collect()
    }
    fn lz_items(&self) -> Vec<(&K, &V)> {
        self.iter().collect()
    }
    fn lz_len(&self) -> i64 {
        self.len() as i64
    }
    fn lz_is_empty(&self) -> bool {
        self.is_empty()
    }
    fn lz_clear(&mut self) {
        self.clear();
    }
    fn lz_update(&mut self, other: HashMap<K, V>) {
        self.extend(other);
    }
    fn lz_set_default(&mut self, key: K, default: V) -> &V
    where
        K: Clone + Eq + Hash,
        V: Clone,
    {
        self.entry(key.clone()).or_insert(default);
        self.get(&key).unwrap()
    }
}

// ══════════════════════════════════════════════════════════════
// HashSet / Set 扩展方法
// ══════════════════════════════════════════════════════════════

pub trait SetExt<T> {
    fn lz_add(&mut self, item: T) -> bool
    where
        T: Eq + Hash;
    fn lz_remove(&mut self, item: &T) -> bool
    where
        T: Eq + Hash;
    fn lz_contains(&self, item: &T) -> bool
    where
        T: Eq + Hash;
    fn lz_len(&self) -> i64;
    fn lz_is_empty(&self) -> bool;
    fn lz_clear(&mut self);
    fn lz_union(&self, other: &HashSet<T>) -> HashSet<T>
    where
        T: Clone + Eq + Hash;
    fn lz_intersection(&self, other: &HashSet<T>) -> HashSet<T>
    where
        T: Clone + Eq + Hash;
}

impl<T: Eq + Hash> SetExt<T> for HashSet<T> {
    fn lz_add(&mut self, item: T) -> bool {
        self.insert(item)
    }
    fn lz_remove(&mut self, item: &T) -> bool {
        self.remove(item)
    }
    fn lz_contains(&self, item: &T) -> bool {
        self.contains(item)
    }
    fn lz_len(&self) -> i64 {
        self.len() as i64
    }
    fn lz_is_empty(&self) -> bool {
        self.is_empty()
    }
    fn lz_clear(&mut self) {
        self.clear();
    }
    fn lz_union(&self, other: &HashSet<T>) -> HashSet<T>
    where
        T: Clone + Eq + Hash,
    {
        self.union(other).cloned().collect()
    }
    fn lz_intersection(&self, other: &HashSet<T>) -> HashSet<T>
    where
        T: Clone + Eq + Hash,
    {
        self.intersection(other).cloned().collect()
    }
}

// ══════════════════════════════════════════════════════════════
// String 扩展方法
// ══════════════════════════════════════════════════════════════

pub trait StringExt {
    fn lz_len(&self) -> i64;
    fn lz_is_empty(&self) -> bool;
    fn lz_contains(&self, substr: &str) -> bool;
    fn lz_starts_with(&self, prefix: &str) -> bool;
    fn lz_ends_with(&self, suffix: &str) -> bool;
    fn lz_split(&self, delimiter: &str) -> Vec<String>;
    fn lz_join(&self, iter: Vec<String>) -> String;
    fn lz_replace(&self, from: &str, to: &str) -> String;
    fn lz_trim(&self) -> String;
    fn lz_to_upper(&self) -> String;
    fn lz_to_lower(&self) -> String;
    fn lz_slice(&self, start: i64, end: i64) -> String;
    fn lz_find(&self, substr: &str) -> Option<i64>;
}

impl StringExt for String {
    fn lz_len(&self) -> i64 {
        self.len() as i64
    }
    fn lz_is_empty(&self) -> bool {
        self.is_empty()
    }
    fn lz_contains(&self, substr: &str) -> bool {
        self.contains(substr)
    }
    fn lz_starts_with(&self, prefix: &str) -> bool {
        self.starts_with(prefix)
    }
    fn lz_ends_with(&self, suffix: &str) -> bool {
        self.ends_with(suffix)
    }
    fn lz_split(&self, delimiter: &str) -> Vec<String> {
        self.split(delimiter).map(|s| s.to_string()).collect()
    }
    fn lz_join(&self, iter: Vec<String>) -> String {
        iter.join(self)
    }
    fn lz_replace(&self, from: &str, to: &str) -> String {
        self.replace(from, to)
    }
    fn lz_trim(&self) -> String {
        self.trim().to_string()
    }
    fn lz_to_upper(&self) -> String {
        self.to_uppercase()
    }
    fn lz_to_lower(&self) -> String {
        self.to_lowercase()
    }
    fn lz_slice(&self, start: i64, end: i64) -> String {
        let s = start.max(0) as usize;
        let e = (end as usize).min(self.len());
        if s >= e {
            return String::new();
        }
        self[s..e].to_string()
    }
    fn lz_find(&self, substr: &str) -> Option<i64> {
        self.find(substr).map(|i| i as i64)
    }
}


// ══════════════════════════════════════════════════════════════
// Map — 映射迭代器
// ══════════════════════════════════════════════════════════════

pub struct Map<I, F> {
    pub iter: I,
    pub func: F,
}

impl<I: Iterator, F: FnMut(I::Item) -> B, B> Iterator for Map<I, F> {
    type Item = B;
    fn next(&mut self) -> Option<B> {
        self.iter.next().map(&mut self.func)
    }
    fn size_hint(&self) -> (usize, Option<usize>) {
        self.iter.size_hint()
    }
}

pub fn lz_map<I: IntoIterator, F: FnMut(I::Item) -> B, B>(iter: I, f: F) -> Map<I::IntoIter, F> {
    Map {
        iter: iter.into_iter(),
        func: f,
    }
}

// ══════════════════════════════════════════════════════════════
// Filter — 过滤迭代器
// ══════════════════════════════════════════════════════════════

pub struct Filter<I, P> {
    pub iter: I,
    pub pred: P,
}

impl<I: Iterator, P: FnMut(&I::Item) -> bool> Iterator for Filter<I, P> {
    type Item = I::Item;
    fn next(&mut self) -> Option<I::Item> {
        while let Some(item) = self.iter.next() {
            if (self.pred)(&item) {
                return Some(item);
            }
        }
        None
    }
}

pub fn lz_filter<I: IntoIterator, P: FnMut(&I::Item) -> bool>(
    iter: I,
    pred: P,
) -> Filter<I::IntoIter, P> {
    Filter {
        iter: iter.into_iter(),
        pred,
    }
}

// ══════════════════════════════════════════════════════════════
// Enumerate — 枚举迭代器
// ══════════════════════════════════════════════════════════════

pub struct Enumerate<I> {
    pub iter: I,
    pub index: i64,
}

impl<I: Iterator> Iterator for Enumerate<I> {
    type Item = (i64, I::Item);
    fn next(&mut self) -> Option<(i64, I::Item)> {
        self.iter.next().map(|item| {
            let idx = self.index;
            self.index += 1;
            (idx, item)
        })
    }
}

pub fn lz_enumerate<I: IntoIterator>(iter: I) -> Enumerate<I::IntoIter> {
    Enumerate {
        iter: iter.into_iter(),
        index: 0,
    }
}

// ══════════════════════════════════════════════════════════════
// Zip — 同时迭代两个迭代器
// ══════════════════════════════════════════════════════════════

pub struct Zip<A, B> {
    pub a: A,
    pub b: B,
}

impl<A: Iterator, B: Iterator> Iterator for Zip<A, B> {
    type Item = (A::Item, B::Item);
    fn next(&mut self) -> Option<(A::Item, B::Item)> {
        match (self.a.next(), self.b.next()) {
            (Some(a), Some(b)) => Some((a, b)),
            _ => None,
        }
    }
}

pub fn lz_zip<A: IntoIterator, B: IntoIterator>(a: A, b: B) -> Zip<A::IntoIter, B::IntoIter> {
    Zip {
        a: a.into_iter(),
        b: b.into_iter(),
    }
}

// ══════════════════════════════════════════════════════════════
// Chain — 链式连接两个迭代器
// ══════════════════════════════════════════════════════════════

pub struct Chain<A, B> {
    pub first: A,
    pub second: B,
    pub first_done: bool,
}

impl<A: Iterator, B: Iterator<Item = A::Item>> Iterator for Chain<A, B> {
    type Item = A::Item;
    fn next(&mut self) -> Option<A::Item> {
        if !self.first_done {
            match self.first.next() {
                Some(item) => return Some(item),
                None => self.first_done = true,
            }
        }
        self.second.next()
    }
}

pub fn lz_chain<A: IntoIterator, B: IntoIterator<Item = A::Item>, I: IntoIterator>(
    first: I,
    second: B,
) -> Chain<I::IntoIter, B::IntoIter>
where
    I::Item: Into<A::Item>,
    I: IntoIterator,
    I::IntoIter: Iterator,
{
    Chain {
        first: first.into_iter(),
        second: second.into_iter(),
        first_done: false,
    }
}

// ══════════════════════════════════════════════════════════════
// Take — 取前 n 个元素
// ══════════════════════════════════════════════════════════════

pub struct Take<I> {
    pub iter: I,
    pub remaining: i64,
}

impl<I: Iterator> Iterator for Take<I> {
    type Item = I::Item;
    fn next(&mut self) -> Option<I::Item> {
        if self.remaining <= 0 {
            return None;
        }
        self.remaining -= 1;
        self.iter.next()
    }
}

pub fn lz_take<I: IntoIterator>(iter: I, n: i64) -> Take<I::IntoIter> {
    Take {
        iter: iter.into_iter(),
        remaining: n,
    }
}

// ══════════════════════════════════════════════════════════════
// Skip — 跳过前 n 个元素
// ══════════════════════════════════════════════════════════════

pub struct Skip<I> {
    pub iter: I,
    pub to_skip: i64,
}

impl<I: Iterator> Iterator for Skip<I> {
    type Item = I::Item;
    fn next(&mut self) -> Option<I::Item> {
        while self.to_skip > 0 {
            self.iter.next();
            self.to_skip -= 1;
        }
        self.iter.next()
    }
}

pub fn lz_skip<I: IntoIterator>(iter: I, n: i64) -> Skip<I::IntoIter> {
    Skip {
        iter: iter.into_iter(),
        to_skip: n,
    }
}

// ══════════════════════════════════════════════════════════════
// Repeat — 无限重复迭代器
// ══════════════════════════════════════════════════════════════

pub struct Repeat<T: Clone> {
    pub value: T,
}

impl<T: Clone> Iterator for Repeat<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        Some(self.value.clone())
    }
}

pub fn lz_repeat<T: Clone>(value: T) -> Repeat<T> {
    Repeat { value }
}

// ══════════════════════════════════════════════════════════════
// Once — 单元素迭代器
// ══════════════════════════════════════════════════════════════

pub struct Once<T> {
    pub value: Option<T>,
}

impl<T> Iterator for Once<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        self.value.take()
    }
}

pub fn lz_once<T>(value: T) -> Once<T> {
    Once { value: Some(value) }
}

// ══════════════════════════════════════════════════════════════
// Empty — 空迭代器
// ══════════════════════════════════════════════════════════════

pub struct Empty<T>(std::marker::PhantomData<T>);

impl<T> Iterator for Empty<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        None
    }
}

pub fn lz_empty<T>() -> Empty<T> {
    Empty(std::marker::PhantomData)
}

// ══════════════════════════════════════════════════════════════
// Range — LZ 范围迭代器 [start, end)
// ══════════════════════════════════════════════════════════════

pub struct LzRange {
    pub current: i64,
    pub end: i64,
    pub step: i64,
}

impl Iterator for LzRange {
    type Item = i64;
    fn next(&mut self) -> Option<i64> {
        if self.step > 0 && self.current >= self.end {
            return None;
        }
        if self.step < 0 && self.current <= self.end {
            return None;
        }
        let val = self.current;
        self.current += self.step;
        Some(val)
    }
}

pub fn lz_range(start: i64, end: i64) -> LzRange {
    LzRange {
        current: start,
        end,
        step: 1,
    }
}

pub fn lz_range_step(start: i64, end: i64, step: i64) -> LzRange {
    LzRange {
        current: start,
        end,
        step,
    }
}

// ══════════════════════════════════════════════════════════════
// Collect — 收集迭代器为 List
// ══════════════════════════════════════════════════════════════

pub fn lz_collect<T, I: IntoIterator<Item = T>>(iter: I) -> Vec<T> {
    iter.into_iter().collect()
}


use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

// ══════════════════════════════════════════════════════════════
// 类型元信息
// ══════════════════════════════════════════════════════════════

#[derive(Debug, Clone, Copy)]
pub enum TypeKind {
    Int,
    UInt,
    Float,
    Bool,
    Char,
    Str,
    Ptr,
    Struct(&'static TypeInfo),
    Unknown,
}

impl PartialEq for TypeKind {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (TypeKind::Int, TypeKind::Int) => true,
            (TypeKind::UInt, TypeKind::UInt) => true,
            (TypeKind::Float, TypeKind::Float) => true,
            (TypeKind::Bool, TypeKind::Bool) => true,
            (TypeKind::Char, TypeKind::Char) => true,
            (TypeKind::Str, TypeKind::Str) => true,
            (TypeKind::Ptr, TypeKind::Ptr) => true,
            (TypeKind::Unknown, TypeKind::Unknown) => true,
            (TypeKind::Struct(a), TypeKind::Struct(b)) => std::ptr::eq(*a, *b),
            _ => false,
        }
    }
}
impl Eq for TypeKind {}

#[derive(Debug, Clone, Copy)]
pub struct FieldInfo {
    pub name: &'static str,
    pub offset: usize,
    pub kind: TypeKind,
    pub type_info: Option<&'static TypeInfo>,
}

#[derive(Debug, Clone, Copy)]
pub struct TypeInfo {
    pub name: &'static str,
    pub size: usize,
    pub fields: &'static [FieldInfo],
}

// ══════════════════════════════════════════════════════════════
// 全局注册表
// ══════════════════════════════════════════════════════════════

static REGISTRY: OnceLock<Mutex<HashMap<&'static str, &'static TypeInfo>>> = OnceLock::new();

fn registry() -> &'static Mutex<HashMap<&'static str, &'static TypeInfo>> {
    REGISTRY.get_or_init(|| Mutex::new(HashMap::new()))
}

pub fn init() {
    let _ = registry();
}

pub fn register(ti: &'static TypeInfo) -> Result<(), &'static str> {
    let mut map = registry().lock().unwrap();
    if map.contains_key(ti.name) {
        return Err(ti.name);
    }
    map.insert(ti.name, ti);
    Ok(())
}

pub fn find_type(name: &str) -> Option<&'static TypeInfo> {
    registry().lock().unwrap().get(name).copied()
}

pub fn type_count() -> usize {
    registry().lock().unwrap().len()
}
pub fn clear() {
    registry().lock().unwrap().clear();
}

pub fn field_count(ti: &TypeInfo) -> usize {
    ti.fields.len()
}
pub fn field(ti: &TypeInfo, idx: usize) -> Option<&FieldInfo> {
    ti.fields.get(idx)
}
pub fn find_field<'a>(ti: &'a TypeInfo, name: &str) -> Option<&'a FieldInfo> {
    ti.fields.iter().find(|f| f.name == name)
}

/// # Safety: data must point to initialized object matching type_info
pub unsafe fn get_raw(
    type_info: &TypeInfo,
    data: *const u8,
    field_name: &str,
    dst: &mut [u8],
) -> Result<(), &'static str> {
    let fi = find_field(type_info, field_name).ok_or("field not found")?;
    let src = data.add(fi.offset);
    let copy_size = dst.len().min(type_info.size.saturating_sub(fi.offset));
    std::ptr::copy_nonoverlapping(src, dst.as_mut_ptr(), copy_size);
    Ok(())
}

/// # Safety: data must point to mutable initialized object matching type_info
pub unsafe fn set_raw(
    type_info: &TypeInfo,
    data: *mut u8,
    field_name: &str,
    src: &[u8],
) -> Result<(), &'static str> {
    let fi = find_field(type_info, field_name).ok_or("field not found")?;
    let dst = data.add(fi.offset);
    let copy_size = src.len().min(type_info.size.saturating_sub(fi.offset));
    std::ptr::copy_nonoverlapping(src.as_ptr(), dst, copy_size);
    Ok(())
}

macro_rules! typed_getset {
    ($get:ident, $set:ident, $kind:path, $ty:ty) => {
        pub unsafe fn $get(
            type_info: &TypeInfo,
            data: *const u8,
            field_name: &str,
        ) -> Result<$ty, &'static str> {
            let fi = find_field(type_info, field_name).ok_or("field not found")?;
            if !matches!(fi.kind, $kind | TypeKind::Unknown) {
                return Err("type kind mismatch");
            }
            Ok(std::ptr::read_unaligned(data.add(fi.offset) as *const $ty))
        }
        pub unsafe fn $set(
            type_info: &TypeInfo,
            data: *mut u8,
            field_name: &str,
            val: $ty,
        ) -> Result<(), &'static str> {
            let fi = find_field(type_info, field_name).ok_or("field not found")?;
            if !matches!(fi.kind, $kind | TypeKind::Unknown) {
                return Err("type kind mismatch");
            }
            std::ptr::write_unaligned(data.add(fi.offset) as *mut $ty, val);
            Ok(())
        }
    };
}

typed_getset!(get_i64, set_i64, TypeKind::Int, i64);
typed_getset!(get_i32, set_i32, TypeKind::Int, i32);
typed_getset!(get_i16, set_i16, TypeKind::Int, i16);
typed_getset!(get_i8, set_i8, TypeKind::Int, i8);
typed_getset!(get_u64, set_u64, TypeKind::UInt, u64);
typed_getset!(get_u32, set_u32, TypeKind::UInt, u32);
typed_getset!(get_u16, set_u16, TypeKind::UInt, u16);
typed_getset!(get_u8, set_u8, TypeKind::UInt, u8);
typed_getset!(get_f64, set_f64, TypeKind::Float, f64);
typed_getset!(get_f32, set_f32, TypeKind::Float, f32);
typed_getset!(get_bool, set_bool, TypeKind::Bool, bool);
typed_getset!(get_char, set_char, TypeKind::Char, char);

/// 安全读取字符串字段
pub unsafe fn get_str<'a>(
    type_info: &TypeInfo,
    data: *const u8,
    field_name: &str,
) -> Result<&'a str, &'static str> {
    let fi = find_field(type_info, field_name).ok_or("field not found")?;
    if !matches!(fi.kind, TypeKind::Str | TypeKind::Unknown) {
        return Err("type kind mismatch");
    }
    Ok((&*(data.add(fi.offset) as *const String)).as_str())
}

/// 安全写入字符串字段
pub unsafe fn set_str(
    type_info: &TypeInfo,
    data: *mut u8,
    field_name: &str,
    val: String,
) -> Result<(), &'static str> {
    let fi = find_field(type_info, field_name).ok_or("field not found")?;
    if !matches!(fi.kind, TypeKind::Str | TypeKind::Unknown) {
        return Err("type kind mismatch");
    }
    std::ptr::write(data.add(fi.offset) as *mut String, val);
    Ok(())
}

pub fn status_str(err: &'static str) -> &'static str {
    err
}

